\begin{algorithm}
\caption{LLM token sampling}
\begin{algorithmic}
\Function{sample}{$L$}
\State $s \gets ()$
\For{$i \gets 1, L$}
\State $\alpha \gets \text{LM}(s, \theta)$
\State Sample $w \sim \text{Categorical}(\alpha)$
\If{$w = \text{EOS}$}
\State \textbf{break}
\EndIf
\State $s \gets \operatorname{append}(s, w)$
\EndFor
\State \Return $s$
\EndFunction
\end{algorithmic}
\end{algorithm}
```

